// Torah Router v2.0 - Strict Validation
// NO silent fallback - reject invalid payloads with HTTP 400

const input = $input.first().json;
const body = input.body || input;
const headers = input.headers || {};

const CHUNK_THRESHOLD = 10000;
const UUID_REGEX = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const VALID_KINDS = ['segment', 'commentary'];

// Helper: validate UUID
const isValidUUID = (str) => str && UUID_REGEX.test(str);

// Helper: create error response
const errorResponse = (code, message) => [{
  json: {
    valid: false,
    error: { code: 400, errorCode: code, message: message }
  }
}];

// ============================================
// VALIDATION v2.0: Strict, no fallback
// ============================================

// 1. Validate 'kind' field (REQUIRED)
const kind = body.kind;
if (!kind) {
  return errorResponse('MISSING_KIND', "Field 'kind' is required. Must be 'segment' or 'commentary'.");
}
if (!VALID_KINDS.includes(kind)) {
  return errorResponse('INVALID_KIND', `Invalid kind '${kind}'. Must be 'segment' or 'commentary'.`);
}

// 2. Validate conditional IDs based on kind
if (kind === 'segment') {
  const segmentId = body.segment_id;
  if (!segmentId) {
    return errorResponse('MISSING_SEGMENT_ID', "Field 'segment_id' is required when kind='segment'.");
  }
  if (!isValidUUID(segmentId)) {
    return errorResponse('INVALID_UUID', `Field 'segment_id' must be a valid UUID. Got: '${segmentId}'.`);
  }
}

if (kind === 'commentary') {
  const commentaryDetailId = body.commentary_detail_id;
  if (!commentaryDetailId) {
    return errorResponse('MISSING_COMMENTARY_DETAIL_ID', "Field 'commentary_detail_id' is required when kind='commentary'.");
  }
  if (!isValidUUID(commentaryDetailId)) {
    return errorResponse('INVALID_UUID', `Field 'commentary_detail_id' must be a valid UUID. Got: '${commentaryDetailId}'.`);
  }
}

// 3. Validate api_key
if (!body.api_key) {
  return errorResponse('MISSING_API_KEY', "Field 'api_key' is required in the request body.");
}

// 4. Validate text or segments
if (!body.text && (!body.segments || !Array.isArray(body.segments) || body.segments.length === 0)) {
  return errorResponse('MISSING_TEXT', "Either 'text' or 'segments[]' is required.");
}

// ============================================
// PARSING: Build internal structure
// ============================================

const jobIdProvided = !!body.job_id;
const jobId = body.job_id || 'job_' + Date.now().toString(36) + Math.random().toString(36).substring(2, 8);
const projectId = headers['x-project-id'] || body.project_id || 'default';
const requestId = body.request_id || 'req_' + Date.now().toString(36);

let pipelineType = 'unknown';
let segments = [];
let needsChunking = false;
let totalSegments = 0;

if (body.segments && Array.isArray(body.segments) && body.segments.length > 0) {
  // Batch mode: multiple segments
  pipelineType = 'batch';

  // Validate each segment has required ID based on kind
  for (let idx = 0; idx < body.segments.length; idx++) {
    const s = body.segments[idx];

    if (kind === 'segment' && !isValidUUID(s.segment_id)) {
      return errorResponse('INVALID_SEGMENT_IN_BATCH', `Segment[${idx}]: 'segment_id' must be a valid UUID when kind='segment'.`);
    }
    if (kind === 'commentary' && !isValidUUID(s.commentary_detail_id)) {
      return errorResponse('INVALID_SEGMENT_IN_BATCH', `Segment[${idx}]: 'commentary_detail_id' must be a valid UUID when kind='commentary'.`);
    }
  }

  segments = body.segments.map((s, idx) => {
    const text = typeof s === 'string' ? s : (s.text || s.text_hebrew || s.hebrew_text || '');
    return {
      index: idx,
      text: text,
      segment_id: kind === 'segment' ? s.segment_id : null,
      commentary_detail_id: kind === 'commentary' ? s.commentary_detail_id : null,
      reference_translation: s.reference_translation || null,
      char_count: text.length
    };
  });

  // Check max length
  const tooLongSegment = segments.find(s => s.char_count > CHUNK_THRESHOLD);
  if (tooLongSegment) {
    return errorResponse('SEGMENT_TOO_LONG', `Segment ${tooLongSegment.index} is too long (${tooLongSegment.char_count} chars). Max: ${CHUNK_THRESHOLD}.`);
  }

  totalSegments = segments.length;

} else if (body.text) {
  // Single text mode
  const textLength = body.text.length;

  if (textLength > CHUNK_THRESHOLD) {
    pipelineType = 'chunk_then_translate';
    needsChunking = true;
    totalSegments = 1; // Will be updated after chunking
  } else {
    pipelineType = 'translate_single';
    totalSegments = 1;
  }

  segments = [{
    index: 0,
    text: body.text,
    segment_id: kind === 'segment' ? body.segment_id : null,
    commentary_detail_id: kind === 'commentary' ? body.commentary_detail_id : null,
    reference_translation: body.reference_translation || null,
    char_count: textLength
  }];
}

// ============================================
// OUTPUT: Validated and parsed data
// ============================================

return [{
  json: {
    valid: true,
    // Routing
    kind: kind,
    jobId: jobId,
    jobIdProvided: jobIdProvided,
    needsJobCreation: !jobIdProvided,
    projectId: projectId,
    requestId: requestId,
    // Pipeline
    jobType: body.job_type || 'translation',
    pipelineType: pipelineType,
    needsChunking: needsChunking,
    // Segments
    segments: segments,
    totalSegments: totalSegments,
    // Context
    traite: body.traite || body.context?.traite,
    page: body.page || body.context?.page,
    section: body.section || body.context?.section,
    commentator: body.commentator || body.context?.commentator,
    // Languages
    sourceLanguage: body.source_language || 'he',
    targetLanguage: body.target_language || 'fr',
    // Auth
    apiKey: body.api_key,
    openaiApiKey: body.openai_api_key,
    // Metadata
    context: body.context || {},
    metadata: body.metadata || {},
    chunkThreshold: CHUNK_THRESHOLD
  }
}];

// Prepare segments for translation loop (after chunking)
const input = $('Parse Input').first().json;
const chunkResult = $input.first().json;

let segments = [];

if (chunkResult.segments && Array.isArray(chunkResult.segments)) {
  segments = chunkResult.segments.map((s, idx) => ({
    index: idx,
    text: s.text,
    segment_id: input.segments[0]?.segment_id,
    commentary_detail_id: input.segments[0]?.commentary_detail_id,
    char_count: s.text?.length || 0,
    isChunk: true,
    totalChunks: chunkResult.segments.length
  }));
} else {
  segments = input.segments;
}

const items = segments.map(segment => ({
  json: {
    ...segment,
    kind: input.kind,
    jobId: input.jobId,
    totalSegments: segments.length,
    traite: input.traite,
    page: input.page,
    section: input.section,
    commentator: input.commentator,
    sourceLanguage: input.sourceLanguage,
    targetLanguage: input.targetLanguage,
    apiKey: input.apiKey,
    openaiApiKey: input.openaiApiKey,
    context: input.context,
    metadata: input.metadata,
    pipelineType: input.pipelineType
  }
}));

return items;

// Use original segments directly (no chunking)
const input = $('Parse Input').first().json;

const items = input.segments.map(segment => ({
  json: {
    ...segment,
    kind: input.kind,
    jobId: input.jobId,
    totalSegments: input.totalSegments,
    traite: input.traite,
    page: input.page,
    section: input.section,
    commentator: input.commentator,
    sourceLanguage: input.sourceLanguage,
    targetLanguage: input.targetLanguage,
    apiKey: input.apiKey,
    openaiApiKey: input.openaiApiKey,
    context: input.context,
    metadata: input.metadata,
    pipelineType: input.pipelineType
  }
}));

return items;

// Prepare save payload - route by kind, no source_text as identifier
const loopItem = $('Loop Segments').first().json;
const translateResult = $input.first().json;

// Base payload - use correct ID field based on kind
const targetPayload = {
  jobId: loopItem.jobId,
  kind: loopItem.kind,
  segmentIndex: loopItem.index,
  totalSegments: loopItem.totalSegments,
  translation: translateResult.translation,
  // ID based on kind (mutually exclusive)
  segment_id: loopItem.kind === 'segment' ? loopItem.segment_id : null,
  commentary_detail_id: loopItem.kind === 'commentary' ? loopItem.commentary_detail_id : null,
  // NO source_text as identifier - it was causing ambiguous payload errors
  targetLanguage: loopItem.targetLanguage,
  provider: 'anthropic',
  model: 'claude-sonnet-4',
  metadata: loopItem.metadata,
  isChunk: loopItem.isChunk || false,
  pipelineType: loopItem.pipelineType,
  method: translateResult.method || 'unknown'
};

// Handle EN pivot generation
const hasGeneratedEnglish = translateResult.generated_english === true && translateResult.english_pivot;

if (hasGeneratedEnglish) {
  const englishPayload = {
    ...targetPayload,
    translation: translateResult.english_pivot,
    targetLanguage: 'en',
    metadata: { ...loopItem.metadata, is_generated_pivot: true },
    pipelineType: 'en_pivot_generation',
    method: 'structured_generation',
    isEnglishPivot: true
  };

  return [
    { json: englishPayload },
    { json: { ...targetPayload, hasEnglishPivotSaved: true } }
  ];
}

return [{ json: targetPayload }];

// Update progress after each segment
const loopItem = $('Loop Segments').first().json;
const current = loopItem.index + 1;
const total = loopItem.totalSegments;
const percentage = Math.round((current / total) * 100);

return [{
  json: {
    jobId: loopItem.jobId,
    current: current,
    total: total,
    percentage: percentage,
    isLast: current >= total
  }
}];
